class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        const int CHARSET = 256;
        vector<int> last(CHARSET, -1);
        int left = 0, ans = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            unsigned char c = s[i];
            if (last[c] >= left) {
                left = last[c] + 1;
            }
            last[c] = i;
            ans = max(ans, i - left + 1);
        }
        return ans;
    }
};
